#include "AdvancedSecurityMetrics.h"
#include <iostream>
#include <fstream>
#include <map>
#include <vector>
using namespace std;
AdvancedSecurityMetrics::AdvancedSecurityMetrics(SecurityLogger& l):logger(l){}
namespace {struct Metrics{int total=0,loginSuccess=0,loginFailed=0,granted=0,denied=0,threats=0,highRisk=0,caseEvents=0,alerts=0;map<string,int> actions;};Metrics calculate(const vector<vector<string>>& logs){Metrics m;for(auto&f:logs){if(f.size()<6)continue;++m.total;++m.actions[f[4]];if(f[4]=="LOGIN"){if(f[5]=="SUCCESS")++m.loginSuccess;if(f[5].find("FAILED")==0)++m.loginFailed;}if(f[4].find("RESOURCE_ACCESS")==0){if(f[5]=="GRANTED")++m.granted;if(f[5].find("DENIED")==0)++m.denied;}if(f[4].find("THREAT_")==0||f[4]=="THREAT_SIMULATION")++m.threats;if(f[4].find("RISK_ASSESSMENT")==0&&f[5].find("HIGH")!=string::npos)++m.highRisk;if(f[4].find("SECURITY_CASE_")==0)++m.caseEvents;if(f[4].find("ALERT_")==0)++m.alerts;}return m;}void writeMetrics(ostream& out,const Metrics&m,const string& scope){out<<"VIGILX ADVANCED SECURITY METRICS\nScope: "<<scope<<"\n\n"<<"Total events: "<<m.total<<"\nSuccessful logins: "<<m.loginSuccess<<"\nFailed logins: "<<m.loginFailed<<"\nAccess granted: "<<m.granted<<"\nAccess denied: "<<m.denied<<"\nThreat simulation events: "<<m.threats<<"\nHigh-risk assessments: "<<m.highRisk<<"\nCase-related events: "<<m.caseEvents<<"\nAlert-related events: "<<m.alerts<<"\n\nEvents by action:\n";for(auto&p:m.actions)out<<p.first<<','<<p.second<<'\n';}}
void AdvancedSecurityMetrics::showMetrics()const{auto logs=logger.readLogs();auto all=calculate(logs);size_t start=logs.size()>20?logs.size()-20:0;vector<vector<string>> recent(logs.begin()+static_cast<long>(start),logs.end());auto r=calculate(recent);cout<<"\n===== ADVANCED SECURITY METRICS =====\nAll-time events: "<<all.total<<"\nLast 20 events (or fewer): "<<r.total<<"\nSuccessful logins: "<<all.loginSuccess<<"\nFailed logins: "<<all.loginFailed<<"\nAccess granted/denied: "<<all.granted<<"/"<<all.denied<<"\nThreat simulation events: "<<all.threats<<"\nHigh-risk assessments: "<<all.highRisk<<"\nCase-related events: "<<all.caseEvents<<"\nAlert-related events: "<<all.alerts<<"\nAction counts:\n";for(auto&p:all.actions)cout<<"  "<<p.first<<": "<<p.second<<'\n';}
void AdvancedSecurityMetrics::exportMetrics()const{auto logs=logger.readLogs();auto all=calculate(logs);size_t start=logs.size()>20?logs.size()-20:0;vector<vector<string>> recent(logs.begin()+static_cast<long>(start),logs.end());auto r=calculate(recent);ofstream t("advanced_security_metrics.txt",ios::trunc);ofstream c("advanced_security_metrics.csv",ios::trunc);if(!t||!c){cout<<"Could not create metrics files.\n";return;}writeMetrics(t,all,"all available local log events");writeMetrics(t,r,"last 20 available local log events");c<<"Metric,AllTime,Last20Events\n"<<"Total events,"<<all.total<<','<<r.total<<'\n'<<"Successful logins,"<<all.loginSuccess<<','<<r.loginSuccess<<'\n'<<"Failed logins,"<<all.loginFailed<<','<<r.loginFailed<<'\n'<<"Access granted,"<<all.granted<<','<<r.granted<<'\n'<<"Access denied,"<<all.denied<<','<<r.denied<<'\n'<<"Threat simulation events,"<<all.threats<<','<<r.threats<<'\n'<<"High-risk assessments,"<<all.highRisk<<','<<r.highRisk<<'\n'<<"Case-related events,"<<all.caseEvents<<','<<r.caseEvents<<'\n'<<"Alert-related events,"<<all.alerts<<','<<r.alerts<<'\n';cout<<"Saved advanced_security_metrics.txt and advanced_security_metrics.csv.\n";}
void AdvancedSecurityMetrics::runMenu(const string&u,const string&r){if(r!="Admin"&&r!="SecurityAnalyst"){cout<<"Access denied.\n";logger.logEvent(u,r,"ADVANCED_METRICS","DENIED_NOT_AUTHORIZED");return;}int c;do{cout<<"\n===== ADVANCED SECURITY METRICS =====\n1. View Metrics\n2. Export TXT/CSV Metrics\n0. Return\nChoice: ";if(!(cin>>c)){cin.clear();cin.ignore(100000,'\n');cout<<"Invalid input.\n";continue;}cin.ignore(100000,'\n');switch(c){case 1:showMetrics();break;case 2:exportMetrics();logger.logEvent(u,r,"ADVANCED_METRICS_EXPORT","SUCCESS");break;case 0:break;default:cout<<"Invalid choice.\n";}}while(c!=0);}
